const handleSubmit = async (e) => {
  e.preventDefault();
  try {
    const { data } = await axios.post("http://localhost:6161/api/auth/jwtlogin", { email, password });

    console.log("Login API Response:", data); // Debugging step

    if (data.user) {
      localStorage.setItem("token", data.token);
      localStorage.setItem("user", JSON.stringify(data.user)); // Store user in storage
      login(data.user); // Set user in context
    }

    alert("Login successful!");
    navigate("/jwtdashboard");
  } catch (error) {
    console.error("Login Error:", error.response?.data);
    alert(error.response?.data?.error || "Login failed!");
  }
};
